import { NodeSDK } from '@opentelemetry/sdk-trace-node';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-http';
import { Resource } from '@opentelemetry/resources';
import { SemanticResourceAttributes } from '@opentelemetry/semantic-conventions';
import * as fs from 'fs';
import * as path from 'path';

// Configure OpenTelemetry SDK to export traces to the local OTLP collector
const sdk = new NodeSDK({
  resource: new Resource({
    [SemanticResourceAttributes.SERVICE_NAME]: 'voltagent-tracing-app',
  }),
  traceExporter: new OTLPTraceExporter({
    url: 'http://localhost:4318/v1/traces',
  }),
});

// Start the SDK
sdk.start();

import { Agent } from "@voltagent/core";
import { openai } from "@ai-sdk/openai";

// Create the agent
const agent = new Agent({
  name: "Assistant",
  instructions: "You are a helpful assistant.",
  model: openai("gpt-4o-mini"),
} as any);

async function main() {
  const logPath = path.join(__dirname, 'output.log');
  try {
    // Send a single message "Hello" to the agent
    // Using generateText and passing experimental_telemetry to enable tracing.
    const result = await agent.generateText("Hello", {
      experimental_telemetry: {
        isEnabled: true,
        metadata: {
          agentId: "assistant-agent",
        },
      },
    } as any);

    const output = result.text;
    fs.writeFileSync(logPath, output);
    console.log(output);
  } catch (error) {
    console.error("Error during agent execution:", error);
    fs.writeFileSync(logPath, `Error: ${error instanceof Error ? error.message : String(error)}`);
  } finally {
    // Flush the tracer and shut down the SDK
    await sdk.shutdown();
    // Explicitly exit the process as OTel and VoltAgent may keep the event loop alive
    process.exit(0);
  }
}

main().catch((error) => {
  console.error("Unhandled error:", error);
  process.exit(1);
});

